script.text:
			/* <flatten type="Javascript"> */
function load$GridDetail$d2(g) {
	g.add_commandEvent(on$GridDetail$d2$ExecuteCommand);
	g.add_itemValueChanged(onChange$GridDetail$d2$);
	g.add_onResponseComplete(on$GridVoucherDetail$d2$ResponseComplete);
	g.add_onRender(on$GridDetail$d2$GridRender);
	g.$a = {
		tong_da_tt: '[tong_da_tt]:=[da_tt0]+[da_tt1]+[tttt_cdt0]+[tttt_cdt1]'
		, con_pt: '[con_pt]:=[tien] - ([tong_da_tt])'
		, tien_lai_tre_han: '[tien_lai_tre_han]:=[tien_lai_da_tt]+[tien_lai_ch_tt]'
		, tien_lai_con_tt: '[tien_lai_con_tt]:=[tien_lai_tre_han]-[tien_lai_mien_giam]-[tien_lai_kh_tt]'
		, _2da_tt: ['_2da_tt', 'tong_da_tt']
		, d2_tien: ['d2_tien', 'tien']
		, d2_da_tt: ['d2_da_tt', '[da_tt0]+[da_tt1]', '1 == 1']
		, d2_tttt_cdt: ['d2_tttt_cdt', '[tttt_cdt0]+[tttt_cdt1]', '1 == 1']

		, d2_tong_da_tt: '[d2_tong_da_tt]:=[d2_da_tt]+[d2_tttt_cdt]'
		, d2_con_pt: '[d2_con_pt]:=[d2_tien]-([d2_da_tt]+[d2_tttt_cdt])'
		, d2_da_xuat_hd: ['d2_da_xuat_hd', 'da_xuat_hd']
		, d2_ty_le: ['d2_ty_le', 'ty_le']

	};
}
function dispose$GridDetail$d2(g) {
	try {g.remove_commandEvent(on$GridDetail$d2$ExecuteCommand);} catch (ex) {}
	try {g.remove_itemValueChanged(onChange$GridDetail$d2$);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridVoucherDetail$d2$ResponseComplete);} catch (ex) {}
	try {g.remove_onRender(on$GridDetail$d2$GridRender);} catch (ex) {}
}
/* </flatten> */
function on$GridDetail$d2$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm, id = g.get_id(), s = String.format('$find(\'{0}\')._focusWhenTabChanged();', id);
	switch (action) {
		&Clipboard.Event.Before;
		&Clipboard.Event.Before.Request;
		&Clipboard.Event.Before.Process;
		&Clipboard.Event.After;
		&Clipboard.Event.After.Process;
		&GridExtraToolbarExecuteCommandScript;
		case 'adjustValue':
			var msg = (g._language == 'v' ? 'Hệ thống sẽ <span class="Highlight">điều chỉnh</span> giá trị phải thanh toán và giá trị đã thanh toán, bạn có chắc chắn thực hiện không?' : 'Are you sure you want to <span class="Highlight">adjust values?</span>?');
			$message.show(msg, 0, String.format('request$Action$d2(\'{0}\', "{1}");', id, action), s);
			break;
		default:
			break;
	}
}
function request$Action$d2(id, c) {
	var g = $find(id), f = g.get_element().parentForm;

	if (c == 'adjustValue') {
		var ld = '';
		var colIndex = [], cols = ['ma_dot', 'ty_le'];

		for (var i = 0; i < cols.length; i++) {colIndex.push(g._getColumnOrder(cols[i]));}

		for (var r = 1; r <= g._rowCount; r++) {
			ld += String.fromCharCode(252) + r.toString();

			for (var i = 0; i < colIndex.length; i++) {
				ld += String.fromCharCode(253) + g._getItemValue(r, colIndex[i]);
			}
		}

		f.request('adjustValue$d1', 'adjustValue$d2', [['_tien_sau_ck', 'Decimal', f.getItemValue('_2tien_sau_ck2')], ['ld', 'Infinite', ld]], null);
	}
}
function onChange$GridDetail$d2$(sender, eventArgs) {
	var o = eventArgs.get_object(), g = o.grid, f = g.get_element().parentForm, name = o.field.Name;
	switch (name) {
		case 'tien':
			g.validExpression(o, [g.$a.con_pt], [], []);
			on$GridDetail$d2$Summary(g);
			break;
		case 'tien_lai_da_tt':
		case 'tien_lai_ch_tt':
			g.validExpression(o, [g.$a.tien_lai_tre_han, g.$a.tien_lai_con_tt], [], []);
			on$GridDetail$d2$Summary(g);
			break;
		case 'tien_lai_mien_giam':
		case 'tien_lai_kh_tt':
			g.validExpression(o, [g.$a.tien_lai_con_tt], [], []);
			on$GridDetail$d2$Summary(g);
			break;
		default:
			break;
	}
}
function on$GridVoucherDetail$d2$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object, f = g.get_element().parentForm;
	switch (context) {
		case 'RenewalDate':
			g.setItemGridBehavior(o, [['so_ngay_gia_han', result[0].Value, null, null]]);
			break;
		default:
			break;
	}
}
function onChange$d2$Date(o) {
	o.grid.request(o, 'RenewalDate', 'RenewalDate', ['han_tt', 'ngay_den_han'], [], null);
}
function on$GridDetail$d2$GridRender(sender, eventArgs) {on$GridDetail$d2$Summary(eventArgs.grid);}
function on$GridDetail$d2$Summary(g) {
	var f = g.get_element().parentForm;
	g.executeAggregate([g.$a.d2_tien, g.$a.d2_da_tt, g.$a.d2_tttt_cdt, g.$a.d2_da_xuat_hd, g.$a.d2_ty_le]);
	f.executeExpression([g.$a.d2_tong_da_tt, g.$a.d2_con_pt]);
}

			&GridExtraToolbarScript;
